"Set-Location 'D:\\AI\\projects\\Reverse_penetration\\Reverse_UsbEAmSource\\UsbEAmSource'\n$pe = [System.IO.File]::ReadAllBytes('D:\\_tools_\\UsbEAm_Launcher_1.0.3\\UsbEAm_Launcher\\UsbEAm_Launcher.exe')\n# PE header offset\n$peh = [System.BitConverter]::ToUInt32($pe, 0x3C)\n# Section headers start at peh+24; each 40 bytes; .text is typically section 0\n# Actually iterate to find .text\nfor ($i = 0; $i -lt 16; $i++) {\n    $shoff = $peh + 24 + 40*$i\n    $name = [System.Text.Encoding]::ASCII.GetString($pe, $shoff, 8).TrimEnd([char]0)\n    if ($name -eq '.text') {\n        $vaddr = [System.BitConverter]::ToUInt32($pe, $shoff + 12)\n        $vsize = [System.BitConverter]::ToUInt32($pe, $shoff + 8)\n        $raw = [System.BitConverter]::ToUInt32($pe, $shoff + 20)\n        $rawsize = [System.BitConverter]::ToUInt32($pe, $shoff + 16)\n        Write-Host \".text: vaddr=0x$($vaddr.ToString('X')) vsize=0x$($vsize.ToString('X')) raw=0x$($raw.ToString('X')) rawsize=0x$($rawsize.ToString('X'))\"\n        $va = 0x1407e4560 - 0x140000000\n        $foff = $raw + ($va - $vaddr)\n        Write-Host \"File offset for VA 0x7E4560: 0x$($foff.ToString('X'))\"\n        # Extract 928 bytes (0x3A0)\n        $size = 0x3A0\n        $bytes = $pe[$foff..($foff+$size-1)]\n        $hex = ($bytes | ForEach-Object { $_.ToString('X2') }) -join ' '\n        $outPath = 'work\\disasm\\b396_CheckpointSections.bin'\n        [System.IO.File]::WriteAllBytes($outPath, $bytes)\n        Write-Host \"Wrote $size bytes to $outPath\"\n        break\n    }\n}\n"